package com.shoply.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="order_items") public class OrderItemEntity {@Id private UUID id;@ManyToOne @JoinColumn(name="order_id",nullable=false)private OrderEntity order;@Column(name="product_id")private UUID productId;@Column(name="product_name",nullable=false)private String productName;@Column(name="unit_price",nullable=false)private BigDecimal unitPrice;@Column(nullable=false)private int quantity;protected OrderItemEntity(){}public OrderItemEntity(UUID id,OrderEntity order,UUID productId,String productName,BigDecimal unitPrice,int quantity){this.id=id;this.order=order;this.productId=productId;this.productName=productName;this.unitPrice=unitPrice;this.quantity=quantity;}public UUID getProductId(){return productId;}public String getProductName(){return productName;}public BigDecimal getUnitPrice(){return unitPrice;}public int getQuantity(){return quantity;}}
